package com.genealogy.source.repository;
import com.baomidou.mybatisplus.core.toolkit.Wrappers; import com.genealogy.common.persistence.*; import com.genealogy.source.entity.SourceBindingEntity; import com.genealogy.source.repository.mybatis.SourceBindingPersistenceMapper; import org.springframework.data.domain.*; import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Repository @Transactional(readOnly=true) public class SourceBindingRepository { private final SourceBindingPersistenceMapper mapper; public SourceBindingRepository(SourceBindingPersistenceMapper mapper){this.mapper=mapper;} @Transactional public SourceBindingEntity save(SourceBindingEntity e){if(e.getId()==null)mapper.insert(e);else if(mapper.updateAllById(e)!=1)throw new IllegalStateException("Source binding update expected one row for id "+e.getId());return e;} @Transactional public SourceBindingEntity saveAndFlush(SourceBindingEntity e){return save(e);} public Optional<SourceBindingEntity> findById(Long id){return Optional.ofNullable(id==null?null:mapper.selectById(id));} @Transactional public void deleteById(Long id){if(id!=null)mapper.deleteById(id);} public List<SourceBindingEntity> findByTargetTypeAndTargetIdOrderByCreatedAtDesc(String t,Long id){return list(Wrappers.<SourceBindingEntity>lambdaQuery().eq(SourceBindingEntity::getTargetType,t).eq(SourceBindingEntity::getTargetId,id));} public List<SourceBindingEntity> findBySourceIdOrderByCreatedAtDesc(Long sourceId){return list(Wrappers.<SourceBindingEntity>lambdaQuery().eq(SourceBindingEntity::getSourceId,sourceId));} public List<SourceBindingEntity> findBySourceIdIn(Collection<Long> ids){return ids==null||ids.isEmpty()?List.of():list(Wrappers.<SourceBindingEntity>lambdaQuery().in(SourceBindingEntity::getSourceId,ids));} public List<SourceBindingEntity> findBySourceIdAndBindingStatusNotOrderByCreatedAtDesc(Long id,String excluded){return list(Wrappers.<SourceBindingEntity>lambdaQuery().eq(SourceBindingEntity::getSourceId,id).ne(SourceBindingEntity::getBindingStatus,excluded));} public Page<SourceBindingEntity> findBySourceIdOrderByCreatedAtDesc(Long id,Pageable p){return page(Wrappers.<SourceBindingEntity>lambdaQuery().eq(SourceBindingEntity::getSourceId,id),p);} public Page<SourceBindingEntity> findBySourceIdAndBindingStatusNotOrderByCreatedAtDesc(Long id,String x,Pageable p){return page(Wrappers.<SourceBindingEntity>lambdaQuery().eq(SourceBindingEntity::getSourceId,id).ne(SourceBindingEntity::getBindingStatus,x),p);} public Page<SourceBindingEntity> findBySourceIdAndTargetTypeOrderByCreatedAtDesc(Long id,String t,Pageable p){return page(Wrappers.<SourceBindingEntity>lambdaQuery().eq(SourceBindingEntity::getSourceId,id).eq(SourceBindingEntity::getTargetType,t),p);} public Page<SourceBindingEntity> findBySourceIdAndTargetTypeAndBindingStatusNotOrderByCreatedAtDesc(Long id,String t,String x,Pageable p){return page(Wrappers.<SourceBindingEntity>lambdaQuery().eq(SourceBindingEntity::getSourceId,id).eq(SourceBindingEntity::getTargetType,t).ne(SourceBindingEntity::getBindingStatus,x),p);} public Page<SourceBindingEntity> findByClanIdAndTargetTypeAndTargetIdOrderByCreatedAtDesc(Long clanId,String t,Long id,Pageable p){return page(Wrappers.<SourceBindingEntity>lambdaQuery().eq(SourceBindingEntity::getClanId,clanId).eq(SourceBindingEntity::getTargetType,t).eq(SourceBindingEntity::getTargetId,id),p);} public Page<SourceBindingEntity> findByClanIdAndSourceIdOrderByCreatedAtDesc(Long clanId,Long sourceId,Pageable p){return page(Wrappers.<SourceBindingEntity>lambdaQuery().eq(SourceBindingEntity::getClanId,clanId).eq(SourceBindingEntity::getSourceId,sourceId),p);} public List<SourceBindingEntity> findTop5BySourceIdOrderByCreatedAtDesc(Long id){return top(Wrappers.<SourceBindingEntity>lambdaQuery().eq(SourceBindingEntity::getSourceId,id),5);} public List<SourceBindingEntity> findTop5BySourceIdAndBindingStatusNotOrderByCreatedAtDesc(Long id,String x){return top(Wrappers.<SourceBindingEntity>lambdaQuery().eq(SourceBindingEntity::getSourceId,id).ne(SourceBindingEntity::getBindingStatus,x),5);} public List<SourceBindingEntity> findTop10ByClanIdAndTargetTypeAndTargetIdAndBindingStatusNotOrderByCreatedAtDesc(Long clanId,String t,Long id,String x){return top(Wrappers.<SourceBindingEntity>lambdaQuery().eq(SourceBindingEntity::getClanId,clanId).eq(SourceBindingEntity::getTargetType,t).eq(SourceBindingEntity::getTargetId,id).ne(SourceBindingEntity::getBindingStatus,x),10);} public List<TargetCountProjection> countActiveByTargets(Long clanId,String t,Collection<Long> ids,String x){return ids==null||ids.isEmpty()?List.of():new ArrayList<>(mapper.countActiveByTargets(clanId,t,ids,x));} public List<SourceBindingEntity> findTreeBindingsByTargets(Long clanId,Collection<String> types,Collection<Long> ids){return types==null||types.isEmpty()||ids==null||ids.isEmpty()?List.of():mapper.findTreeBindingsByTargets(clanId,types,ids);} public boolean existsBySourceIdAndTargetTypeAndTargetId(Long s,String t,Long id){return mapper.selectCount(Wrappers.<SourceBindingEntity>lambdaQuery().eq(SourceBindingEntity::getSourceId,s).eq(SourceBindingEntity::getTargetType,t).eq(SourceBindingEntity::getTargetId,id))>0;} public boolean existsBySourceIdAndTargetTypeAndTargetIdAndBindingStatusNot(Long s,String t,Long id,String x){return mapper.selectCount(Wrappers.<SourceBindingEntity>lambdaQuery().eq(SourceBindingEntity::getSourceId,s).eq(SourceBindingEntity::getTargetType,t).eq(SourceBindingEntity::getTargetId,id).ne(SourceBindingEntity::getBindingStatus,x))>0;} public int countBySourceId(Long id){return Math.toIntExact(mapper.selectCount(Wrappers.<SourceBindingEntity>lambdaQuery().eq(SourceBindingEntity::getSourceId,id)));} public int countBySourceIdAndBindingStatusNot(Long id,String x){return Math.toIntExact(mapper.selectCount(Wrappers.<SourceBindingEntity>lambdaQuery().eq(SourceBindingEntity::getSourceId,id).ne(SourceBindingEntity::getBindingStatus,x)));} private List<SourceBindingEntity> list(com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<SourceBindingEntity>q){q.orderByDesc(SourceBindingEntity::getCreatedAt).orderByDesc(SourceBindingEntity::getId);return mapper.selectList(q);} private List<SourceBindingEntity> top(com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<SourceBindingEntity>q,int n){q.orderByDesc(SourceBindingEntity::getCreatedAt).orderByDesc(SourceBindingEntity::getId).last("limit "+n);return mapper.selectList(q);} private Page<SourceBindingEntity> page(com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<SourceBindingEntity>q,Pageable p){long total=mapper.selectCount(q);if(total==0)return new PageImpl<>(List.of(),p,0);q.orderByDesc(SourceBindingEntity::getCreatedAt).orderByDesc(SourceBindingEntity::getId).last("limit "+p.getPageSize()+" offset "+p.getOffset());return new PageImpl<>(mapper.selectList(q),p,total);} }
